78	        variant="ghost"
79	        className={["group p-2", className].filter(Boolean).join(" ")}
80	        aria-label={ariaLabel}
81	        aria-pressed={isFavorite}
82	        disabled={isPending}
83	        data-favorite-button
84	        onClick={(e) => {
85	          e.preventDefault();
86	          e.stopPropagation();
87	
88	          trackClick();
89	          setLimitMessage(null);
90	          const nextIsFavorite = !isFavorite;
91	          setIsFavorite(nextIsFavorite);
92	
93	          startTransition(async () => {
94	            isMutatingRef.current = true;
95	            try {
96	              const response = await queueFavoriteRequest(() =>
97	                fetch("/api/favorites", {
98	                  method: "POST",
99	                  headers: { "Content-Type": "application/json" },
100	                  body: JSON.stringify({
101	                    eventSlug,
102	                    shouldBeFavorite: nextIsFavorite,
103	                  }),
104	                })
105	              );
106	
107	              if (!response.ok) {
108	                const payload = (await response.json().catch(() => null)) as unknown;
109	                if (response.status === 409 && isMaxReachedPayload(payload)) {
110	                  const max = parseMaxFavorites(payload);
111	                  sendGoogleEvent("favorites_limit_reached", {
112	                    action: "add",
113	                    max_favorites: max,
114	                    event_slug: eventSlug,
115	                    event_id: eventId,
116	                    event_title: eventTitle,
117	                  });
118	                  setLimitMessage(t("maxReached", { max: max ?? "" }));
119	                  setIsFavorite(!nextIsFavorite);
120	                  return;
121	                }
122	
123	                throw new Error("Failed to update favorites");
124	              }
125	
126	              const payload = (await response.json().catch(() => null)) as unknown;
127	              if (
128	                payload &&
129	                typeof payload === "object" &&
130	                "favorites" in payload &&
131	                Array.isArray((payload as { favorites?: unknown }).favorites)
132	              ) {
133	                const favorites = (payload as { favorites: unknown[] }).favorites
134	                  .filter((value): value is string => typeof value === "string")
135	                  .map((value) => value.trim())
136	                  .filter(Boolean);
137	
138	                mutateFavorites({ ok: true, favorites }, { revalidate: false });
139	              }
140	
141	              const analyticsEventName = nextIsFavorite
142	                ? "favorite_add"
143	                : "favorite_remove";
144	
145	              sendGoogleEvent(analyticsEventName, {
146	                event_slug: eventSlug,
147	                event_id: eventId,
148	                event_title: eventTitle,
149	              });
150	
151	              // Preserve existing /preferits UX: reflect removals immediately.
152	              // Avoid refreshing other pages to keep the toggle lightweight.
153	              if (window.location.pathname.endsWith("/preferits")) {
154	                router.refresh();
155	              }
156	            } catch (error: unknown) {
157	              captureException(error, {
158	                tags: { feature: "favorites" },
159	                extra: {
160	                  event_slug: eventSlug,
161	                  event_id: eventId,
162	                  event_title: eventTitle,
163	                  next_is_favorite: nextIsFavorite,
164	                },
165	              });
166	              setIsFavorite(!nextIsFavorite);
167	            } finally {
168	              isMutatingRef.current = false;
169	            }
170	          });
171	        }}
172	      >
173	        <Icon className={`h-6 w-6 text-primary transition-[transform,color] duration-200 group-hover:scale-[1.06] group-active:scale-[0.96] ${isFavorite ? "animate-heartBeat" : ""}`} />
174	      </Button>
175	
176	      {limitMessage && (
177	        <div
178	          role="status"
179	          aria-live="polite"
180	          className="absolute right-0 top-full mt-1 w-56 rounded-input border border-border bg-background p-2 body-small text-foreground/80"
181	        >
182	          {limitMessage}
183	        </div>
184	      )}
185	    </div>
186	  );
